package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/department") public class DepartmentController{private final DepartmentService s;public DepartmentController(DepartmentService s){this.s=s;}@PostMapping public ResponseEntity<DepartmentDTO> create(@Valid @RequestBody DepartmentDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<DepartmentDTO> all(){return s.all();}@GetMapping("/{id}") public DepartmentDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public DepartmentDTO update(@PathVariable Long id,@Valid @RequestBody DepartmentDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
